                    {/* Upcoming Bills */}
                    <div className="glass-card p-4 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col relative overflow-hidden">
                        <div className="absolute top-0 right-0 p-3 opacity-10"><Clock className="w-12 h-12 text-amber-500" /></div>
                        <div className="flex justify-between items-center mb-3 shrink-0 relative z-10">
                            <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Upcoming</h3>
                            <CalendarClock className="w-3 h-3 text-amber-500" />
                        </div>
                        <div className="space-y-3 overflow-y-auto custom-scrollbar flex-1 relative z-10 pr-1">
                            {upcomingBills.length > 0 ? (
                                upcomingBills.map((bill, i) => (
                                    <div key={i} className="flex items-center gap-2 group">
                                        <div className="w-6 h-6 rounded-full flex items-center justify-center text-[8px] font-black text-slate-400 bg-slate-800 border border-white/5 shrink-0">
