                                        </div>
                                        <div className="flex-1 min-w-0">
                                            <div className="flex justify-between items-center">
                                                <span className="text-[9px] font-bold text-slate-300 truncate">{bill.merchant}</span>
                                                <span className="text-[9px] font-bold text-white">{formatCurrency(bill.amount)}</span>
                                            </div>
                                            <div className={`text-[8px] font-bold ${bill.daysLeft < 3 ? 'text-amber-400' : 'text-slate-500'}`}>
                                                {bill.daysLeft <= 0 ? 'Due Now' : `In ${bill.daysLeft}d`}
                                            </div>
                                        </div>
                                    </div>
                                ))
                            ) : (
                                <div className="flex flex-col items-center justify-center h-full opacity-40">
                                    <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest text-center">All clear</span>
                                </div>
                            )}
                        </div>
                    </div>
                </div>

            </div>
        </div>

        {/* Scan Confirmation Modal */}
        {showScanConfirm && (
            <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md animate-fade-in">
                <div className="bg-[#0f172a] border border-white/10 rounded-[2.5rem] w-full max-w-sm p-8 shadow-2xl relative animate-slide-up">
