import React, { useState, useMemo } from 'react';
import { Account, Transaction, Goal, Budget, UserPlan, SpendingStatus, SpendingPeriod, TransactionType, Category } from '../types';
import { 
  Wallet, CreditCard, Sparkles, Target, Landmark, 
  Settings, TrendingUp, ChevronDown, FileText, UserCircle, 
  GitFork, Microscope, Handshake, Gauge, CheckCircle2, 
  Clock, CalendarClock, ArrowUpRight, ArrowDownRight, 
  AlertTriangle, Plus, Activity, Search
} from 'lucide-react';

interface DashboardProps {
  accounts: Account[];
  transactions: Transaction[];
  goals: Goal[];
  budgets: Budget[];
  onNavigate: (tab: string, params?: any) => void;
  onAddTransaction: () => void;
  onAddGoal: () => void;
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
  onAskCoach: (query: string) => void;
  insightUsage: number;
  spendingStatus: SpendingStatus;
  currentPeriodSpend: number;
  spendingLimit: number;
  spendingPeriod: SpendingPeriod;
  userName: string;
  isPrivacyMode: boolean;
}

const CreditScoreGauge = () => {
    const score = 750;
    const max = 850;
    const min = 300;
    const percentage = ((score - min) / (max - min)) * 100;

    return (
        <div className="relative w-full h-full flex flex-col items-center justify-center">
            <svg className="w-24 h-24 transform -rotate-90">
                <circle cx="48" cy="48" r="40" stroke="#1e293b" strokeWidth="8" fill="transparent" />
                <circle 
                    cx="48" cy="48" r="40" 
                    stroke={score >= 700 ? '#10b981' : score >= 600 ? '#f59e0b' : '#f43f5e'} 
                    strokeWidth="8" 
                    fill="transparent" 
                    strokeDasharray={251} 
                    strokeDashoffset={251 - (percentage / 100) * 251} 
                    strokeLinecap="round" 
                />
            </svg>
            <div className="absolute flex flex-col items-center">
                <span className="text-xl font-black text-white">{score}</span>
                <span className="text-[8px] font-bold uppercase tracking-widest text-slate-500">Excellent</span>
            </div>
        </div>
    );
};

const Dashboard: React.FC<DashboardProps> = ({
  accounts,
  transactions,
  goals,
  budgets,
  onNavigate,
  onAddTransaction,
  onAddGoal,
  formatCurrency,
  userPlan,
  onAskCoach,
  insightUsage,
