  const [activeMenu, setActiveMenu] = useState<string | null>(null);

  const toggleMenu = (e: React.MouseEvent, menuId: string) => {
      e.stopPropagation();
      setActiveMenu(activeMenu === menuId ? null : menuId);
  };

  React.useEffect(() => {
      const handleClickOutside = () => setActiveMenu(null);
      window.addEventListener('click', handleClickOutside);
      return () => window.removeEventListener('click', handleClickOutside);
  }, []);

  const totalBalance = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

  const recentTransactions = useMemo(() => transactions.slice(0, 5), [transactions]);

  const { paidBills, upcomingBills } = useMemo(() => {
      const now = new Date();
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();

      const bills = transactions.filter(t => 
          (t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES || t.category === Category.HOUSING) &&
          t.type === TransactionType.EXPENSE
      );

      const paid = bills.filter(t => {
          const d = new Date(t.date);
          return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      }).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

      // Simple heuristic for upcoming bills: 
      // Look for bills paid last month but not yet this month
      const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
      const lastMonthBills = transactions.filter(t => {
          const d = new Date(t.date);
          return d.getMonth() === lastMonth.getMonth() && 
                 d.getFullYear() === lastMonth.getFullYear() &&
                 (t.category === Category.SUBSCRIPTION || t.category === Category.UTILITIES);
      });

      const upcoming = lastMonthBills.filter(lastBill => {
          return !paid.find(p => p.merchant === lastBill.merchant);
      }).map(bill => {
          const d = new Date(bill.date);
          const expectedDate = new Date(currentYear, currentMonth, d.getDate());
          const daysLeft = Math.ceil((expectedDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
          return {
              ...bill,
              date: expectedDate.toISOString(),
              daysLeft
          };
      }).filter(b => b.daysLeft >= 0).sort((a,b) => a.daysLeft - b.daysLeft);

      return { paidBills: paid, upcomingBills: upcoming };
  }, [transactions]);

  return (
    <div className="space-y-6 animate-slide-up pb-10">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-4">
