            Hello, {isPrivacyMode ? 'Pilot' : userName}
          </h2>
          <p className="text-slate-400 mt-2 font-medium">Here is your financial command center.</p>
        </div>
        <div className="flex gap-3">
            <button onClick={onAddTransaction} className="bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-xl text-sm font-bold flex items-center gap-2 shadow-lg shadow-indigo-500/20 active:scale-95 transition-all">
                <Plus className="w-4 h-4" /> Add Transaction
            </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="lg:col-span-2 space-y-6">
            <div className="glass-card p-6 rounded-[2.5rem] border border-white/5 relative overflow-hidden">
                <div className="absolute top-0 right-0 p-10 opacity-10">
                    <Wallet className="w-32 h-32 text-indigo-500" />
                </div>

                <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div>
                        <p className="text-slate-400 text-xs font-bold uppercase tracking-widest mb-1">Total Net Worth</p>
                        <h3 className="text-4xl font-black text-white tracking-tighter mb-4">{formatCurrency(totalBalance)}</h3>

                        <div className="flex gap-2">
                            <div className="px-3 py-1.5 bg-emerald-500/10 border border-emerald-500/20 rounded-lg flex items-center gap-2">
                                <ArrowUpRight className="w-4 h-4 text-emerald-400" />
                                <span className="text-emerald-400 text-xs font-bold">+2.4%</span>
                            </div>
                            <div className="px-3 py-1.5 bg-slate-800/50 border border-white/5 rounded-lg">
                                <span className="text-slate-400 text-xs font-bold">vs last month</span>
                            </div>
                        </div>
                    </div>

                    <div className="bg-slate-900/50 rounded-2xl p-5 border border-white/5">
                        <div className="flex justify-between items-center mb-2">
                            <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">
                                {spendingPeriod === 'monthly' ? 'Monthly' : 'Weekly'} Spend
                            </p>
                            <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wide border ${spendingStatus.colorClass}`}>
                                {spendingStatus.message}
                            </span>
                        </div>
                        <h3 className="text-2xl font-black text-white tracking-tight mb-2">
                            {formatCurrency(currentPeriodSpend)} 
                            <span className="text-slate-500 text-lg font-bold"> / {formatCurrency(spendingLimit)}</span>
                        </h3>
                        <div className="w-full bg-slate-800 h-2 rounded-full overflow-hidden">
                            <div 
                                className={`h-full rounded-full transition-all duration-1000 ${spendingStatus.status === 'violation' ? 'bg-rose-500' : spendingStatus.status === 'warning' ? 'bg-amber-500' : 'bg-indigo-500'}`}
                                style={{ width: `${Math.min(spendingStatus.ratio * 100, 100)}%` }}
                            ></div>
                        </div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-3 gap-3">
                <div className="col-span-2 flex flex-col gap-3">
                    <div className="relative">
                        <button 
                            onClick={(e) => toggleMenu(e, 'overview_menu')}
                            className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors"
                        >
                            Financial Overview <ChevronDown className="w-4 h-4 text-slate-500" />
                        </button>
                        {activeMenu === 'overview_menu' && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-slate-950 border border-white/10 rounded-2xl shadow-xl z-30 overflow-hidden animate-fade-in p-1">
                                <button onClick={() => { onNavigate('insights', { reportType: 'monthly' }); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <FileText className="w-3 h-3 text-emerald-400" /> Monthly Report
                                </button>
                                <button onClick={() => { onAskCoach && onAskCoach(""); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <UserCircle className="w-3 h-3 text-indigo-400" /> Question Coach
                                </button>
                            </div>
                        )}
                    </div>

                    <div className="relative">
                        <button 
                            onClick={(e) => toggleMenu(e, 'tools_menu')}
                            className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-between items-center hover:bg-slate-800 transition-colors"
                        >
                            Smart Money Tools <ChevronDown className="w-4 h-4 text-slate-500" />
                        </button>
                        {activeMenu === 'tools_menu' && (
                            <div className="absolute top-full left-0 right-0 mt-2 bg-slate-950 border border-white/10 rounded-2xl shadow-xl z-30 overflow-hidden animate-fade-in p-1">
                                <button onClick={() => { onNavigate('smart_money', { tab: 'cashflow' }); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <GitFork className="w-3 h-3 text-indigo-400" /> Cashflow Beta
                                </button>
                                <button onClick={() => { onNavigate('smart_money', { tab: 'sandbox' }); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <Microscope className="w-3 h-3 text-amber-400" /> Predictive Sandbox
                                </button>
                                <button onClick={() => { onNavigate('smart_money', { tab: 'negotiator' }); setActiveMenu(null); }} className="w-full text-left px-4 py-3 text-[10px] font-bold text-slate-300 hover:bg-white/5 hover:text-white rounded-xl flex items-center gap-3 uppercase tracking-wider">
                                    <Handshake className="w-3 h-3 text-emerald-400" /> Bill Negotiator
                                </button>
                            </div>
                        )}
                    </div>

                    <button onClick={() => onNavigate('insights', { reportType: 'daily' })} className="w-full p-4 bg-indigo-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-lg shadow-indigo-500/20 hover:bg-indigo-500 transition-colors text-center border border-indigo-500/50 flex justify-center items-center gap-2">
                        Daily Action
                    </button>

                    <button onClick={() => onNavigate('investment')} className="w-full p-4 bg-slate-900/40 border border-white/5 text-slate-300 rounded-2xl text-[10px] font-black uppercase tracking-widest flex justify-center items-center hover:bg-slate-800 transition-colors">
                        Investment Node
                    </button>
                </div>

                <div className="col-span-1 glass-card rounded-[2.5rem] border border-white/5 bg-gradient-to-b from-slate-900/60 to-slate-950/60 p-3 flex flex-col relative overflow-hidden items-center text-center justify-center">
                    <div className="absolute top-0 right-0 p-3 opacity-10"><Gauge className="w-12 h-12 text-white" /></div>
                    <h3 className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2 relative z-10 w-full">Credit Score</h3>
                    <div className="flex-1 min-h-0 relative z-10 w-full flex items-center justify-center">
                        <CreditScoreGauge />
                    </div>
                </div>
            </div>
        </div>

        <div className="space-y-6">
            <div className="flex flex-col gap-3 flex-1 min-h-[200px]">
                <div className="glass-card p-4 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col h-full min-h-[180px]">
                    <div className="flex justify-between items-center mb-3 shrink-0">
                        <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Recent Bills</h3>
                        <CheckCircle2 className="w-3 h-3 text-emerald-500" />
                    </div>
                    <div className="space-y-3 overflow-y-auto custom-scrollbar flex-1 pr-1 max-h-[150px]">
                        {paidBills.length > 0 ? (
                            paidBills.map(bill => (
                                <div key={bill.id} className="flex items-center gap-2 group">
                                    <div className={`w-6 h-6 rounded-full flex items-center justify-center text-[8px] font-black text-white shrink-0 ${bill.merchant.toLowerCase().includes('netflix') ? 'bg-red-600' : bill.merchant.toLowerCase().includes('spotify') ? 'bg-green-500' : 'bg-slate-800'}`}>
                                        {bill.merchant.charAt(0)}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-center">
                                            <span className="text-[9px] font-bold text-slate-300 truncate">{bill.merchant}</span>
                                            <span className="text-[9px] font-bold text-emerald-400">{formatCurrency(bill.amount)}</span>
                                        </div>
                                        <div className="text-[8px] text-slate-600 font-medium">Paid {new Date(bill.date).getDate()}th</div>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full opacity-40">
                                <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest text-center">No recent payments</span>
                            </div>
                        )}
                    </div>
                </div>

                <div className="glass-card p-4 rounded-[2rem] border border-white/5 bg-slate-900/40 flex flex-col relative overflow-hidden h-full min-h-[180px]">
                    <div className="absolute top-0 right-0 p-3 opacity-10"><Clock className="w-12 h-12 text-amber-500" /></div>
                    <div className="flex justify-between items-center mb-3 shrink-0 relative z-10">
                        <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Upcoming</h3>
                        <CalendarClock className="w-3 h-3 text-amber-500" />
                    </div>
                    <div className="space-y-3 overflow-y-auto custom-scrollbar flex-1 relative z-10 pr-1 max-h-[150px]">
                        {upcomingBills.length > 0 ? (
                            upcomingBills.map((bill, i) => (
                                <div key={i} className="flex items-center gap-2 group">
                                    <div className="w-6 h-6 rounded-full flex items-center justify-center text-[8px] font-black text-slate-400 bg-slate-800 border border-white/5 shrink-0">
                                        {bill.merchant.charAt(0)}
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <div className="flex justify-between items-center">
                                            <span className="text-[9px] font-bold text-slate-300 truncate">{bill.merchant}</span>
                                            <span className="text-[9px] font-bold text-white">{formatCurrency(bill.amount)}</span>
                                        </div>
                                        <div className={`text-[8px] font-bold ${bill.daysLeft < 3 ? 'text-amber-400' : 'text-slate-500'}`}>
                                            {bill.daysLeft <= 0 ? 'Due Now' : `In ${bill.daysLeft}d`}
                                        </div>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full opacity-40">
                                <span className="text-[8px] font-bold text-slate-500 uppercase tracking-widest text-center">All clear</span>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            <div className="glass-card p-6 rounded-[2.5rem] border border-white/5">
                <div className="flex justify-between items-center mb-4">
                    <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Activity Log</h3>
                    <button onClick={() => onNavigate('transactions')} className="text-[10px] font-bold text-indigo-400 hover:text-indigo-300">View All</button>
                </div>
                <div className="space-y-4">
                    {recentTransactions.map(tx => (
                        <div key={tx.id} className="flex justify-between items-center">
                            <div className="flex items-center gap-3">
                                <div className={`p-2 rounded-xl ${tx.type === TransactionType.INCOME ? 'bg-emerald-500/10 text-emerald-400' : 'bg-slate-800 text-slate-400'}`}>
                                    {tx.type === TransactionType.INCOME ? <ArrowDownRight className="w-4 h-4" /> : <ArrowUpRight className="w-4 h-4" />}
                                </div>
                                <div>
                                    <p className="text-xs font-bold text-white truncate max-w-[120px]">{tx.merchant}</p>
                                    <p className="text-[10px] text-slate-500">{new Date(tx.date).toLocaleDateString()}</p>
                                </div>
                            </div>
                            <span className={`text-xs font-bold ${tx.type === TransactionType.INCOME ? 'text-emerald-400' : 'text-white'}`}>
                                {tx.type === TransactionType.INCOME ? '+' : ''}{formatCurrency(tx.amount)}
